arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-489b69e151964f9282ae4bbd592b65cb/ShipmentTracker/` using `dotnet new blazor -o ShipmentTracker -int Auto -ai -au Individual`.

This is an Interactive Auto Global project with two sub-projects:
- `ShipmentTracker/` (server) - hosts the app, API endpoints, EF Core data access
- `ShipmentTracker.Client/` (WebAssembly) - all interactive UI components

**CRITICAL Auto mode rules:**
- Interactive components MUST go in the `.Client` project
- Components cannot access DbContext directly - must use HTTP APIs
- Both Program.cs files must register matching service interfaces
- Don't add `@rendermode` to pages - global mode already handles it
- Identity/Account pages must stay as-is (static SSR)

## What to implement

### 1. Shared Models in `.Client` project

Create `ShipmentTracker.Client/Models/ShipmentStatus.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}
```

Create `ShipmentTracker.Client/Models/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CarrierName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
}
```

### 2. Service Interface in `.Client` project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null);
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus);
}
```

### 3. Client-side HttpClient implementation

Create `ShipmentTracker.Client/Services/ClientShipmentService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null)
    {
        var url = "/api/shipments";
        if (!string.IsNullOrEmpty(statusFilter))
            url += $"?status={statusFilter}";
        return await httpClient.GetFromJsonAsync<List<ShipmentDto>>(url) ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await httpClient.GetFromJsonAsync<ShipmentDto>($"/api/shipments/track/{trackingNumber}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await httpClient.PutAsJsonAsync($"/api/shipments/{id}/status", newStatus);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }
}
```

### 4. Register services in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to add after the existing service registrations (before `await builder.Build().RunAsync();`):

```csharp
builder.Services.AddHttpClient<IShipmentService, ClientShipmentService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});
// Also register IShipmentService directly so DI resolves it 
builder.Services.AddScoped<IShipmentService>(sp =>
    sp.GetRequiredService<IHttpClientFactory>().CreateClient(nameof(ClientShipmentService)) is var _ 
    ? sp.GetRequiredService<ClientShipmentService>() 
    : throw new InvalidOperationException());
```

Actually, simpler approach - just use AddScoped with HttpClient:

```csharp
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ClientShipmentService>();
```

### 5. Server-side Data Model

Create `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }

    [MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(100)]
    public string CarrierName { get; set; } = string.Empty;

    public double WeightKg { get; set; }
}
```

### 6. Update ApplicationDbContext

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add a DbSet:

```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
```

### 7. Server-side ShipmentService

Create `ShipmentTracker/Services/ServerShipmentService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == (int)status);
        }

        return await query.OrderByDescending(s => s.ShippedDate)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found.");

        shipment.Status = (int)newStatus;
        await db.SaveChangesAsync();

        return MapToDto(shipment);
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
